\usetikzlibrary{patterns,calc}
\usepackage[colorlinks]{hyperref}

\begin{document}

\begin{tikzpicture}
\newcommand{\crad}{0.7ex} % circle radius
\newcommand{\lht}{-.4} % label height
\newcommand{\xone}{-1.2}
\newcommand{\yone}{0.6}
\newcommand{\xtwo}{1.8}
\newcommand{\ytwo}{4.4}
% gridlines
\draw [very thick, <->] (-2.5,0) -- (5.5,0);
\draw [very thick, ->] (0,0) -- (0,2.5);
% curves
\draw[very thick, ProcessBlue] (\xtwo,0) arc (0:180:\xtwo/2-\xone/2);
\draw[very thick, Red] (\ytwo,0) arc (0:180:\ytwo/2-\yone/2);
% points
\draw[thick, fill=Cyan] (\xone,0) circle (\crad);
\draw[thick, fill=Red] (\yone,0) circle (\crad);
\draw[thick, fill=Cyan] (\xtwo,0) circle (\crad);
\draw[thick, fill=Red] (\ytwo,0) circle (\crad);
% labels
\node at (\xone,\lht) {$x_1^+$};
\node at (\yone,\lht) {$x_1^-$};
\node at (\xtwo,\lht) {$x_2^+$};
\node at (\ytwo,\lht) {$x_2^-$};
\node at (-.7,1.4) {$\gamma^+$};
\node at (4.4,1.4) {$\gamma^-$};
\end{tikzpicture}

\end{document}
