\documentclass[pra,aps,floatfix,superscriptaddress,11pt,tightenlines,longbibliography,onecolumn,notitlepage]{revtex4-1}
\usepackage{amsmath, amsfonts, amssymb, amsthm, braket, bbm, xcolor}
\usepackage{tikz}
\usepackage[pdftex,colorlinks=true,linkcolor=darkblue,citecolor=darkred,urlcolor=blue]{hyperref}

\begin{document}

\begin{tikzpicture}
	% choose fill colors
	[a/.style ={fill=white},
	b/.style ={fill=black!90!white},
	c/.style ={fill=black!20!white}]
	\def\xx{6.4/5} % x step size
	\def\yy{4/3} % y step size
	% rectangles
	\draw[shift={(.5,-.5)}] (0,0) rectangle (6.4,4);
	\draw[b] (0,0) rectangle (6.4,4);
	% shaded grid
	\foreach \x in {0,2,4} {
	\foreach \y in {0,2}
		\draw[shift={(\x*\xx,\y*\yy)},a] (0,0) rectangle (\xx,\yy);
	}
	\draw[shift={(1*\xx,\yy)},a] (0,0) rectangle (\xx,\yy);
	\draw[shift={(3*\xx,\yy)},a] (0,0) rectangle (\xx,\yy);
	% c region
	\foreach \x in {1,2,3,4} {
	\foreach \y in {1,2}
		\draw[shift={(\x*\xx,\y*\yy)},c] (0,0) circle (.25cm);
	}
	% labels
	\node at (\xx/2,5*\yy/2) {$X$};
	\node[color=white] at (\xx/2,3*\yy/2) {$Y$};
	\node at (\xx,\yy) {$Z$};
	\node[below right] at (6.4,0) {$R$};
\end{tikzpicture}

\end{document}
