    \node[rednode] (p2) [right of=p0, below of=p0]  {$p^2_2$};
    \node[blacknode]  [below of = p0] (p3) {$p^2_3$};

    \path[->]
    (p0) edge [bend left] node [] {} (p1)
    (p1) edge [bend left] node [] {} (p2)
    (p2) edge [bend left] node [] {} (p3)
