\documentclass[12pt]{article}
\usepackage[utf8]{inputenc}
\usepackage{tikz}
\usepackage{amsmath}
\usepackage{amssymb}

\begin{document}

\begin{tikzpicture}
            %setting up the 6x6 lattice
            %edges
            \foreach \x in {0,...,5} {
                \draw [black, thick] (0, \x)--(3, \x);
            }
             \foreach \x in {0,...,3} {
                \draw [black, thick] (\x, 0)--(\x, 5);

            }
            %want vertices on top
            \foreach \x in {0,...,3} {
                \foreach \y in {0,...,5} {
                    \draw [black, fill=white] (\x, \y) circle [radius=0.25] node () {};
                }
            }






            %show smallest closed set

            \foreach \x in {0,...,3} {
                    \draw [red, fill=lightgray!50, thick] (\x, 5) circle [radius=0.25] node () {};
                    \draw [red, fill=lightgray!50, thick] (\x, 0) circle [radius=0.25] node () {};
            }
            \foreach \y in {0,...,5} {
                    \draw [red, fill=lightgray!50, thick] (1, \y) circle [radius=0.25] node () {};
            }
            \draw [red, fill=lightgray!50, thick] (1, 1) circle [radius=0.25] node () {$v$};


        \end{tikzpicture}

